LIBS["transpo"] = {"controls":{"transpose":{"args":["interval"],"argType":"interval","description":"Real (chromatic) transposition — shift the alphabet anchor by a fixed interval (fraction 3/2, cents 700c, decimal 1.5). Preserves intervals AND note names; works in any tuning. A bare integer is a ratio N:1 (N-th harmonic): 2/4/8 = octaves; for semitones use cents (12 semitones = 1200c). The old grid-step regime is removed.","scope":["symbol","group","rule","flow","scene"],"transportGroup":"transpo"},"scale":{"bp3":"_scale","args":["name","blockkey"],"default":{"name":0,"blockkey":0},"description":"Microtonal scale — name + base note. (scale:0 0) revient au temperament egal. Le nom et la note de base sont DEUX valeurs, separees par la virgule dans le declaratif et par l'espace dans le flux.","scope":["symbol","group","rule","flow"],"transportGroup":"transpo"},"scaleshift":{"args":["degrees"],"default":0,"description":"Scalar (diatonic) transposition — shift N degrees in the alphabet. (scaleshift:2) : Sa->Ga, etc. Preserves degrees, not intervals (in unequal scales). Formerly rotate-HAUTEUR; distinct from the ![rotate] STRUCTURE control.","scope":["symbol","group","rule","flow"],"transportGroup":"transpo"},"chromashift":{"bp3":"_transpose","args":["keys"],"default":0,"description":"Chromatic transposition on the 12-key grid — shift N chromatic keys (semitones), rename to target key + its tuning. Image of BP3 _transpose (Romain decision 2026-07-17). Distinct from scaleshift (diatonic degrees) and transpose (real, name preserved).","scope":["symbol","group","rule","flow","scene"],"transportGroup":"transpo"},"keyxpand":{"bp3":"_keyxpand","args":["pivot","factor"],"default":{"pivot":0,"factor":1},"description":"Interval expansion/contraction around a pivot. factor=2 doubles, factor=-1 inverts, factor=0.5 contracts.","scope":["symbol","group","rule","flow"],"transportGroup":"transpo"}},"documented":true,"resolves":"transpo","resolvedBy":"Kairos","name":"transpo","description":"Transformations de hauteur résolues par Kairos."};

